<template><aside class="builder-panel recent-panel"><header class="builder-panel__heading"><strong>♙ &nbsp; Recent Activity</strong></header><div class="activity-items"><article v-for="item in activities" :key="item.id"><span>{{ icons[item.platform] }}</span><div><b>{{ item.summary }}</b><strong>{{ item.actor }}</strong><small>{{ item.createdAtLabel }}</small></div><button @click="$emit('replay',item)">Replay</button></article></div></aside></template>
